import math

def parse_obj(filename):
    vertices = []
    normals = []
    faces = [] # (v_indices, mtl_name)
    current_mtl = None
    materials = {}
    mtl_filename = None

    with open(filename, "r") as f:
        lines = f.readlines()

    import os
    obj_dir = os.path.dirname(filename)

    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0] == "mtllib":
            mtl_path = os.path.join(obj_dir, parts[1])
            if os.path.exists(mtl_path):
                materials = parse_mtl(mtl_path)
        elif parts[0] == "usemtl":
            current_mtl = parts[1]
        elif parts[0] == "v":
            vertices.append([float(parts[1]), float(parts[2]), float(parts[3])])
        elif parts[0] == "vn":
            normals.append([float(parts[1]), float(parts[2]), float(parts[3])])
        elif parts[0] == "f":
            v_idxs = []
            for p in parts[1:]:
                v_info = p.split("/")
                v_idxs.append(int(v_info[0]) - 1)
            # Triangulate polygon fan
            for i in range(1, len(v_idxs) - 1):
                faces.append(([v_idxs[0], v_idxs[i], v_idxs[i+1]], current_mtl))
    return vertices, faces, materials

def parse_mtl(filename):
    materials = {}
    current_mat = None
    with open(filename, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"): continue
            parts = line.split()
            if parts[0] == "newmtl":
                current_mat = parts[1]
                materials[current_mat] = (255, 255, 255)
            elif parts[0] == "Kd" and current_mat:
                r, g, b = float(parts[1]), float(parts[2]), float(parts[3])
                materials[current_mat] = (int(r * 255), int(g * 255), int(b * 255))
    return materials

print("Parser prototype ready")
'"}

