static double edge_fn(double ax, double ay, double bx, double by, double cx, double cy) {
    return (cx - ax) * (by - ay) - (cy - ay) * (bx - ax);
}

static void render_frame(const std::vector<Triangle>& triangles, int width, int height,
                         double rx, double ry, double rz, bool colorless, bool webify,
                         std::ostream& os) {
    if (triangles.empty()) return;

    double max_coord = 0.0;
    for (const auto& t : triangles) {
        max_coord = std::max(max_coord, std::abs(t.p0.x));
        max_coord = std::max(max_coord, std::abs(t.p0.y));
        max_coord = std::max(max_coord, std::abs(t.p0.z));
        max_coord = std::max(max_coord, std::abs(t.p1.x));
        max_coord = std::max(max_coord, std::abs(t.p1.y));
        max_coord = std::max(max_coord, std::abs(t.p1.z));
        max_coord = std::max(max_coord, std::abs(t.p2.x));
        max_coord = std::max(max_coord, std::abs(t.p2.y));
        max_coord = std::max(max_coord, std::abs(t.p2.z));
    }
    double scale = (max_coord > 0.0) ? (1.0 / max_coord) : 1.0;

    double cos_x = std::cos(rx), sin_x = std::sin(rx);
    double cos_y = std::cos(ry), sin_y = std::sin(ry);
    double cos_z = std::cos(rz), sin_z = std::sin(rz);

    auto transform = [&](Vec3 p) -> Vec3 {
        p.x *= scale; p.y *= scale; p.z *= scale;
        // Rotate X
        double y1 = p.y * cos_x - p.z * sin_x;
        double z1 = p.y * sin_x + p.z * cos_x;
        double x1 = p.x;
        // Rotate Y
        double x2 = x1 * cos_y + z1 * sin_y;
        double z2 = -x1 * sin_y + z1 * cos_y;
        double y2 = y1;
        // Rotate Z
        double x3 = x2 * cos_z - y2 * sin_z;
        double y3 = x2 * sin_z + y2 * cos_z;
        double z3 = z2;
        return {x3, y3, z3};
    };

    double weff = std::min((double)width, 2.0 * height);
    double heff = weff / 2.0;

    std::vector<std::vector<char>> grid_char(height, std::vector<char>(width, ' '));
    std::vector<std::vector<Color>> grid_color(height, std::vector<Color>(width, {0, 0, 0}));
    std::vector<std::vector<double>> z_buf(height, std::vector<double>(width, -1e18));

    const char ramp[10] = {' ', '.', ':', '-', '=', '+', '*', '#', '%', '@'};

    for (const auto& t : triangles) {
        Vec3 p0 = transform(t.p0);
        Vec3 p1 = transform(t.p1);
        Vec3 p2 = transform(t.p2);

        Vec3 a = {p1.x - p0.x, p1.y - p0.y, p1.z - p0.z};
        Vec3 b = {p2.x - p0.x, p2.y - p0.y, p2.z - p0.z};
        double nx = a.y * b.z - a.z * b.y;
        double ny = a.z * b.x - a.x * b.z;
        double nz = a.x * b.y - a.y * b.x;
        double nl = std::sqrt(nx*nx + ny*ny + nz*nz);
        if (nl == 0.0) continue;
        nx /= nl; ny /= nl; nz /= nl;

        if (nz <= 0.0) continue;

        double intensity = std::max(0.0, std::min(1.0, nz));
        int char_idx = std::min(9, (int)(intensity * 10.0));
        char ch = ramp[char_idx];

        auto to_screen = [&](Vec3 p) -> Vec3 {
            double sx = (double)width / 2.0 + p.x * (weff / 2.0);
            double sy = (double)height / 2.0 - p.y * (heff / 2.0);
            return {sx, sy, p.z};
        };

        Vec3 s0 = to_screen(p0);
        Vec3 s1 = to_screen(p1);
        Vec3 s2 = to_screen(p2);

        int min_x = std::max(0, (int)std::min({s0.x, s1.x, s2.x}));
        int max_x = std::min(width - 1, (int)std::max({s0.x, s1.x, s2.x}));
        int min_y = std::max(0, (int)std::min({s0.y, s1.y, s2.y}));
        int max_y = std::min(height - 1, (int)std::max({s0.y, s1.y, s2.y}));

        double area = edge_fn(s0.x, s0.y, s1.x, s1.y, s2.x, s2.y);
        if (area == 0.0) continue;

        for (int y = min_y; y <= max_y; ++y) {
            for (int x = min_x; x <= max_x; ++x) {
                double px = x + 0.5, py = y + 0.5;
                double w0 = edge_fn(s1.x, s1.y, s2.x, s2.y, px, py);
                double w1 = edge_fn(s2.x, s2.y, s0.x, s0.y, px, py);
                double w2 = edge_fn(s0.x, s0.y, s1.x, s1.y, px, py);

                if ((area > 0 && w0 >= 0 && w1 >= 0 && w2 >= 0) ||
                    (area < 0 && w0 <= 0 && w1 <= 0 && w2 <= 0)) {
                    w0 /= area; w1 /= area; w2 /= area;
                    double z = w0 * s0.z + w1 * s1.z + w2 * s2.z;
                    if (z > z_buf[y][x]) {
                        z_buf[y][x] = z;
                        grid_char[y][x] = ch;
                        grid_color[y][x] = t.color;
                    }
                }
            }
        }
    }

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            char c = grid_char[y][x];
            Color col = grid_color[y][x];
            if (webify) {
                os << "<span style=\"color:rgb(" << col.r << "," << col.g << "," << col.b << ")\">" << c;
            } else if (colorless) {
                os << c;
            } else {
                os << "\x1b[48;2;25;25;25m\x1b[38;2;" << col.r << ";" << col.g << ";" << col.b << "m" << c << "\x1b[49m\x1b[39m";
            }
        }
        os << "\n";
    }
}

