                v[v_cnt++] = {x, y, z};
                if (v_cnt == 3) {
                    triangles.push_back({v[0], v[1], v[2], yellow});
                    v_cnt = 0;
                }
            }
        }
    } else {
        uint32_t count = 0;
        f.read((char*)&count, 4);
        for (uint32_t i = 0; i < count; ++i) {
            float normal[3];
            float v0[3], v1[3], v2[3];
            uint16_t attr;
            f.read((char*)normal, 12);
            f.read((char*)v0, 12);
            f.read((char*)v1, 12);
            f.read((char*)v2, 12);
            f.read((char*)&attr, 2);
            triangles.push_back({{v0[0], v0[1], v0[2]}, {v1[0], v1[1], v1[2]}, {v2[0], v2[1], v2[2]}, yellow});
        }
    }
    return triangles;
}

static std::vector<Triangle> load_file(const std::string& filepath) {
    size_t dot = filepath.find_last_of('.');
    if (dot == std::string::npos) {
        std::cerr << "\nthread 'main' panicked at src/inputs.rs:126:39:\ncalled `Result::unwrap()` on an `Err` value: \"filename: [" << filepath << "] couldn't load, couldn't determine filename extension. \"\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n";
        exit(101);
    }
    std::string ext = filepath.substr(dot);
    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
    if (ext == ".stl") {
        return load_stl(filepath);
    } else {
        return load_obj(filepath);
    }
}

static double edge_fn(double ax, double ay, double bx, double by, double cx, double cy) {
    return (cx - ax) * (by - ay) - (cy - ay) * (bx - ax);
}

static void render_frame(const std::vector<Triangle>& triangles, int width, int height,
                         double rx, double ry, double rz, bool colorless, bool webify,
                         std::ostream& os) {
    if (triangles.empty()) return;

    double max_coord = 0.0;
    for (const auto& t : triangles) {
        max_coord = std::max(max_coord, std::abs(t.p0.x));
        max_coord = std::max(max_coord, std::abs(t.p0.y));
        max_coord = std::max(max_coord, std::abs(t.p0.z));
        max_coord = std::max(max_coord, std::abs(t.p1.x));
        max_coord = std::max(max_coord, std::abs(t.p1.y));
        max_coord = std::max(max_coord, std::abs(t.p1.z));
        max_coord = std::max(max_coord, std::abs(t.p2.x));
        max_coord = std::max(max_coord, std::abs(t.p2.y));
        max_coord = std::max(max_coord, std::abs(t.p2.z));
    }
    double scale = (max_coord > 0.0) ? (1.0 / max_coord) : 1.0;

    double cos_x = std::cos(rx), sin_x = std::sin(rx);
    double cos_y = std::cos(ry), sin_y = std::sin(ry);
    double cos_z = std::cos(rz), sin_z = std::sin(rz);

    auto transform = [&](Vec3 p) -> Vec3 {
        p.x *= scale; p.y *= scale; p.z *= scale;
        // Rotate X
        double y1 = p.y * cos_x - p.z * sin_x;
        double z1 = p.y * sin_x + p.z * cos_x;
        double x1 = p.x;
        // Rotate Y
        double x2 = x1 * cos_y + z1 * sin_y;
        double z2 = -x1 * sin_y + z1 * cos_y;
        double y2 = y1;
        // Rotate Z
        double x3 = x2 * cos_z - y2 * sin_z;
        double y3 = x2 * sin_z + y2 * cos_z;
        double z3 = z2;
        return {x3, y3, z3};
    };

    double weff = 0.8 * std::min((double)width, 2.0 * height);
    double heff = weff / 2.0;

    std::vector<std::vector<char>> grid_char(height, std::vector<char>(width, ' '));
    std::vector<std::vector<Color>> grid_color(height, std::vector<Color>(width, {0, 0, 0}));
    std::vector<std::vector<double>> z_buf(height, std::vector<double>(width, -1e18));

    const char ramp[10] = {' ', '.', ':', '-', '=', '+', '*', '#', '%', '@'};

    for (const auto& t : triangles) {
        Vec3 p0 = transform(t.p0);
        Vec3 p1 = transform(t.p1);
        Vec3 p2 = transform(t.p2);

        Vec3 a = {p1.x - p0.x, p1.y - p0.y, p1.z - p0.z};
        Vec3 b = {p2.x - p0.x, p2.y - p0.y, p2.z - p0.z};
        double nx = a.y * b.z - a.z * b.y;
        double ny = a.z * b.x - a.x * b.z;
        double nz = a.x * b.y - a.y * b.x;
        double nl = std::sqrt(nx*nx + ny*ny + nz*nz);
        if (nl == 0.0) continue;
        nx /= nl; ny /= nl; nz /= nl;

        if (nz <= 0.0) continue;

        double intensity = std::max(0.0, std::min(1.0, nz));
        int char_idx = std::min(9, (int)(intensity * 10.0));
        char ch = ramp[char_idx];

        auto to_screen = [&](Vec3 p) -> Vec3 {
            double sx = (double)width / 2.0 + p.x * (weff / 2.0);
            double sy = (double)height / 2.0 - p.y * (heff / 2.0);
            return {sx, sy, p.z};
        };

        Vec3 s0 = to_screen(p0);
        Vec3 s1 = to_screen(p1);
        Vec3 s2 = to_screen(p2);

        int min_x = std::max(0, (int)std::min({s0.x, s1.x, s2.x}));
        int max_x = std::min(width - 1, (int)std::max({s0.x, s1.x, s2.x}));
        int min_y = std::max(0, (int)std::min({s0.y, s1.y, s2.y}));
        int max_y = std::min(height - 1, (int)std::max({s0.y, s1.y, s2.y}));

        double area = edge_fn(s0.x, s0.y, s1.x, s1.y, s2.x, s2.y);
        if (area == 0.0) continue;

        for (int y = min_y; y <= max_y; ++y) {
            for (int x = min_x; x <= max_x; ++x) {
                double px = x + 0.5, py = y + 0.5;
                double w0 = edge_fn(s1.x, s1.y, s2.x, s2.y, px, py);
                double w1 = edge_fn(s2.x, s2.y, s0.x, s0.y, px, py);
                double w2 = edge_fn(s0.x, s0.y, s1.x, s1.y, px, py);

                if ((area > 0 && w0 >= 0 && w1 >= 0 && w2 >= 0) ||
                    (area < 0 && w0 <= 0 && w1 <= 0 && w2 <= 0)) {
                    w0 /= area; w1 /= area; w2 /= area;
                    double z = w0 * s0.z + w1 * s1.z + w2 * s2.z;
                    if (z > z_buf[y][x]) {
                        z_buf[y][x] = z;
                        grid_char[y][x] = ch;
                        grid_color[y][x] = t.color;
                    }
                }
            }
        }
    }

    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            char c = grid_char[y][x];
            Color col = grid_color[y][x];
            if (webify) {
                os << "<span style=\"color:rgb(" << col.r << "," << col.g << "," << col.b << ")\">" << c;
            } else if (colorless) {
                os << c;
            } else {
                os << "\x1b[48;2;25;25;25m\x1b[38;2;" << col.r << ";" << col.g << ";" << col.b << "m" << c << "\x1b[49m\x1b[39m";
            }
        }
        os << "\n";
    }
}

int main(int argc, char** argv) {
    bool help = false, version = false, colorless = false;
    double yaw = 0.0, pitch = 0.0, roll = 0.0;
    std::vector<std::string> filenames;
    int width = -1, height = -1, webify_frames = -1;
    bool is_image_subcommand = false;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        if (arg == "-h" || arg == "--help") {
            help = true;
        } else if (arg == "-V" || arg == "--version") {
            version = true;
        } else if (arg == "-b") {
            colorless = true;
        } else if (arg == "help") {
            if (i + 1 < argc && std::string(argv[i+1]) == "image") {
                std::cout << "executable-image \nMitchell Hynes <mitchell.hynes@ecumene.xyz>\nGenerates a colorless terminal output as lines of text\n\nUSAGE:\n    executable <input filename(s)>... image [FLAGS] [OPTIONS] -w <width>\n\nFLAGS:\n        --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -j, --webify <frame count>    Generates a portable JS based render of your object for the web\n    -h <height>                   Sets the height of the image to generate\n    -w <width>                    Sets the width of the image to generate\n    -x, --yaw <x>                 Sets the object's static X rotation (in radians)\n    -y, --pitch <y>               Sets the object's static Y rotation (in radians)\n    -z, --roll <z>                Sets the object's static Z rotation (in radians)\n";
                return 0;
            } else {
                std::cout << "Sloth 0.1\nMitchell Hynes. <mshynes@mun.ca>\nA toy for rendering 3D objects in the command line\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -x, --yaw <x>      Sets the object's static X rotation (in radians)\n    -y, --pitch <y>    Sets the object's static Y rotation (in radians)\n    -z, --roll <z>     Sets the object's static Z rotation (in radians)\n\nARGS:\n    <input filename(s)>...    Sets the input file to render\n\nSUBCOMMANDS:\n    help     Prints this message or the help of the given subcommand(s)\n    image    Generates a colorless terminal output as lines of text\n";
                return 0;
            }
        } else if (arg == "image") {
            is_image_subcommand = true;
            for (int j = i + 1; j < argc; ++j) {
                std::string sarg = argv[j];
                if (sarg == "--help") {
                    std::cout << "executable-image \nMitchell Hynes <mitchell.hynes@ecumene.xyz>\nGenerates a colorless terminal output as lines of text\n\nUSAGE:\n    executable <input filename(s)>... image [FLAGS] [OPTIONS] -w <width>\n\nFLAGS:\n        --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -j, --webify <frame count>    Generates a portable JS based render of your object for the web\n    -h <height>                   Sets the height of the image to generate\n    -w <width>                    Sets the width of the image to generate\n    -x, --yaw <x>                 Sets the object's static X rotation (in radians)\n    -y, --pitch <y>               Sets the object's static Y rotation (in radians)\n    -z, --roll <z>                Sets the object's static Z rotation (in radians)\n";
                    return 0;
                } else if (sarg == "-b") {
                    colorless = true;
                } else if (sarg == "-w" && j + 1 < argc) {
                    width = std::stoi(argv[++j]);
                } else if (sarg == "-h" && j + 1 < argc) {
                    height = std::stoi(argv[++j]);
                } else if ((sarg == "-j" || sarg == "--webify") && j + 1 < argc) {
                    webify_frames = std::stoi(argv[++j]);
                } else if ((sarg == "-x" || sarg == "--yaw") && j + 1 < argc) {
                    yaw = std::stod(argv[++j]);
                } else if ((sarg == "-y" || sarg == "--pitch") && j + 1 < argc) {
                    pitch = std::stod(argv[++j]);
                } else if ((sarg == "-z" || sarg == "--roll") && j + 1 < argc) {
                    roll = std::stod(argv[++j]);
                }
            }
            break;
        } else if ((arg == "-x" || arg == "--yaw") && i + 1 < argc) {
            yaw = std::stod(argv[++i]);
        } else if ((arg == "-y" || arg == "--pitch") && i + 1 < argc) {
            pitch = std::stod(argv[++i]);
        } else if ((arg == "-z" || arg == "--roll") && i + 1 < argc) {
            roll = std::stod(argv[++i]);
        } else if (arg[0] != '-') {
            filenames.push_back(arg);
        }
    }

    if (version) {
        std::cout << "Sloth 0.1\n";
        return 0;
    }

    if (help) {
        std::cout << "Sloth 0.1\nMitchell Hynes. <mshynes@mun.ca>\nA toy for rendering 3D objects in the command line\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFLAGS:\n    -h, --help       Prints help information\n    -b               Flags the rasterizer to render without color\n    -V, --version    Prints version information\n\nOPTIONS:\n    -x, --yaw <x>      Sets the object's static X rotation (in radians)\n    -y, --pitch <y>    Sets the object's static Y rotation (in radians)\n    -z, --roll <z>     Sets the object's static Z rotation (in radians)\n\nARGS:\n    <input filename(s)>...    Sets the input file to render\n\nSUBCOMMANDS:\n    help     Prints this message or the help of the given subcommand(s)\n    image    Generates a colorless terminal output as lines of text\n";
        return 0;
    }

    if (filenames.empty()) {
        std::cerr << "error: The following required arguments were not provided:\n    <input filename(s)>...\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]\n\nFor more information try --help\n";
        return 1;
    }

    if (is_image_subcommand) {
        if (width < 0) {
            std::cerr << "error: The following required arguments were not provided:\n    -w <width>\n\nUSAGE:\n    executable image [FLAGS] [OPTIONS] -w <width>\n\nFor more information try --help\n";
            return 1;
        }
        if (height < 0) {
            height = width / 2;
        }

        std::vector<Triangle> all_triangles;
        for (const auto& fn : filenames) {
            auto tris = load_file(fn);
            all_triangles.insert(all_triangles.end(), tris.begin(), tris.end());
        }

        if (webify_frames > 0) {
            std::cout << "let frames = [\n`\n";
            for (int k = 0; k < webify_frames; ++k) {
                double cur_ry = yaw + k * (2.0 * M_PI / webify_frames);
                render_frame(all_triangles, width, height, pitch, cur_ry, roll, colorless, true, std::cout);
                if (k < webify_frames - 1) {
                    std::cout << "`, \n`\n";
                } else {
                    std::cout << "`;\n";
                }
            }
        } else {
            render_frame(all_triangles, width, height, pitch, yaw, roll, colorless, false, std::cout);
        }
        return 0;
    }

    // Interactive mode
    std::vector<Triangle> all_triangles;
    for (const auto& fn : filenames) {
        auto tris = load_file(fn);
        all_triangles.insert(all_triangles.end(), tris.begin(), tris.end());
    }

    struct winsize ws;
    int tw = 80, th = 24;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0 && ws.ws_col > 0) {
        tw = ws.ws_col;
        th = ws.ws_row;
    }

    int flags = fcntl(STDIN_FILENO, F_GETFL, 0);
    fcntl(STDIN_FILENO, F_SETFL, flags | O_NONBLOCK);

    std::cout << "\x1b[?25l" << std::flush;

    double cur_yaw = yaw;
    while (true) {
        std::cout << "\x1b[1;1H";
        render_frame(all_triangles, tw, th, pitch, cur_yaw, roll, colorless, false, std::cout);
        std::cout << std::flush;

        cur_yaw += 0.05;
        std::this_thread::sleep_for(std::chrono::milliseconds(30));

        char ch;
        if (read(STDIN_FILENO, &ch, 1) > 0) {
            if (ch == 'q' || ch == 'Q' || ch == 27) {
                break;
            } else if (ch == 'b' || ch == 'B') {
                colorless = !colorless;
            }
        }
    }

    std::cout << "\x1b[?25h" << std::flush;
    return 0;
}
